const FINISHED = new Set(['C:build', 'C:review', 'C:fix', 'C:gate', 'C:repair', 'C:gate2', 'S1:build', 'S1:review'])
// Owner, later on 2026-10-18: the custom split is lifted; every agent uses the session's default model.
const tier = () => ({})
